    CREATE DATABASE IF NOT EXISTS it_lab_asset_tracking CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
    USE it_lab_asset_tracking;
    DROP TABLE IF EXISTS audit_logs,notifications,loans,borrowers,hardware_items,categories,users;
    CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(150) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('staff','student_assistant','instructor') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
    CREATE TABLE categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
    CREATE TABLE hardware_items(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id INT UNSIGNED NOT NULL,asset_code VARCHAR(80) NOT NULL UNIQUE,item_name VARCHAR(150) NOT NULL,description TEXT,brand VARCHAR(100),model VARCHAR(100),serial_number VARCHAR(150) UNIQUE,quantity INT UNSIGNED NOT NULL DEFAULT 1,condition_status ENUM('good','fair','damaged','maintenance') NOT NULL DEFAULT 'good',availability_status ENUM('available','borrowed','maintenance','unavailable') NOT NULL DEFAULT 'available',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON UPDATE CASCADE ON DELETE RESTRICT);
    CREATE TABLE borrowers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,borrower_name VARCHAR(150) NOT NULL,student_id VARCHAR(80),email VARCHAR(150),contact_number VARCHAR(50),department VARCHAR(120),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
    CREATE TABLE loans(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,borrower_id INT UNSIGNED NOT NULL,hardware_item_id INT UNSIGNED NOT NULL,issued_by INT UNSIGNED NOT NULL,loan_date DATE NOT NULL,due_date DATE NULL,return_date DATE NULL,status ENUM('borrowed','returned','overdue') NOT NULL DEFAULT 'borrowed',remarks TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(borrower_id) REFERENCES borrowers(id) ON DELETE RESTRICT,FOREIGN KEY(hardware_item_id) REFERENCES hardware_items(id) ON DELETE RESTRICT,FOREIGN KEY(issued_by) REFERENCES users(id) ON DELETE RESTRICT);
    CREATE TABLE notifications(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,loan_id INT UNSIGNED NULL,title VARCHAR(180) NOT NULL,message TEXT NOT NULL,type ENUM('return_reminder','overdue','system','general') NOT NULL DEFAULT 'general',is_read TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(loan_id) REFERENCES loans(id) ON DELETE SET NULL);
    CREATE TABLE audit_logs(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,action VARCHAR(50) NOT NULL,table_name VARCHAR(80) NOT NULL,record_id INT UNSIGNED NULL,description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
